import { apiGet } from '../../lib/api/client.js'
import chalk from 'chalk'
import clipboard from 'clipboardy'
import { copied } from '../../lib/output/brand.js'

export default async function formsEmbed(id: string): Promise<void> {
  const data = await apiGet<{ html: string }>(`/api/v1/forms/${id}/embed`, { authenticated: true })
  try {
    await clipboard.write(data.html)
  } catch {
    // ignore
  }
  console.log(data.html)
  console.log(chalk.dim(`\n(copied to clipboard)`))
}
